package com.example.familymenu.family.repository;
import com.example.familymenu.family.domain.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository; import java.util.*; import java.util.concurrent.atomic.AtomicLong;
@Repository @Profile("memory") public class InMemoryFamilyRepository implements FamilyRepository { private final AtomicLong ids=new AtomicLong(); private final Map<Long,Family> families=new HashMap<>(); private final Map<Long,List<FamilyMember>> members=new HashMap<>(); private final AtomicLong mids=new AtomicLong(); public synchronized Family create(String n,String o){long uid=ids.incrementAndGet(),fid=ids.incrementAndGet(); families.put(fid,new Family(fid,n,uid)); members.put(fid,new ArrayList<FamilyMember>()); members.get(fid).add(new FamilyMember(mids.incrementAndGet(),fid,uid,o,"OWNER")); return families.get(fid);} public Optional<Family> findById(Long id){return Optional.ofNullable(families.get(id));} public List<FamilyMember> findMembers(Long id){return new ArrayList<>(members.getOrDefault(id,Collections.<FamilyMember>emptyList()));} public synchronized FamilyMember addMember(Long id,String n,String r){long uid=ids.incrementAndGet();FamilyMember m=new FamilyMember(mids.incrementAndGet(),id,uid,n,r);members.get(id).add(m);return m;} public synchronized boolean removeMember(Long id,Long mid){List<FamilyMember> ms=members.get(id);if(ms==null)return false;return ms.removeIf(m->m.getId().equals(mid)&&!"OWNER".equals(m.getRole()));} }
